/** The categories table. */
object CategoryTable : Table("categories") {
    val id = long("id").autoIncrement()
    val name = varchar("name", 80).nullable()
    val parentId = long("parent_id").nullable()

    override val primaryKey = PrimaryKey(id)
}

/** Keeps categories in the database with Exposed. */
class ExposedCategoryRepository(private val database: Database) : CategoryRepository {
    override suspend fun list(query: ListQuery): ListResult<Category> = suspendTransaction(database) {
        val select = CategoryTable.selectAll()
        for ((field, value) in query.filters) {
            when (field) {
                "id" -> select.andWhere { CategoryTable.id eq (value as Long) }
                "name" -> select.andWhere { CategoryTable.name eq (value as String) }
                "parentId" -> select.andWhere { CategoryTable.parentId eq (value as Long) }
            }
        }
        val total = select.count()
        val sorted = when (query.sortField) {
            "id" -> CategoryTable.id
            "name" -> CategoryTable.name
            "parentId" -> CategoryTable.parentId
            else -> null
        }
        // Items without a value go last, whatever the order; the key breaks ties
        if (sorted != null) select.orderBy(sorted, if (query.descending) SortOrder.DESC_NULLS_LAST else SortOrder.ASC_NULLS_LAST)
        select.orderBy(CategoryTable.id, SortOrder.ASC)
        if (query.limit != null) select.limit(query.limit).offset(query.offset.toLong())
        ListResult(select.map(::toItem), total)
    }

    override suspend fun get(key: Long): Category? = suspendTransaction(database) {
        CategoryTable.selectAll().where { CategoryTable.id eq key }.singleOrNull()?.let(::toItem)
    }

    override suspend fun add(item: Category): Category {
        val key = suspendTransaction(database) {
            CategoryTable.insert { fill(it, item) } get CategoryTable.id
        }
        // Read back, so the answer has what the database keeps
        return get(key)!!
    }

    override suspend fun update(item: Category): Category {
        suspendTransaction(database) { CategoryTable.update({ CategoryTable.id eq item.id }) { fill(it, item) } }
        return get(item.id)!!
    }

    override suspend fun delete(key: Long) {
        suspendTransaction(database) { CategoryTable.deleteWhere { CategoryTable.id eq key } }
    }

    /** Every column but the key takes the value of the item. */
    private fun fill(row: UpdateBuilder<*>, item: Category) {
        row[CategoryTable.name] = item.name
        row[CategoryTable.parentId] = item.parentId
    }

    private fun toItem(row: ResultRow) = Category(
        id = row[CategoryTable.id],
        name = row[CategoryTable.name],
        parentId = row[CategoryTable.parentId],
    )
}

